types.12_SceKernelSm1Ops:
/* sceKernelSm1ReferOperations() result; only the 0xC entry is used here */
typedef struct SceKernelSm1Ops {
    void *unk0;
    void *unk4;
    void *unk8;
    s32 (*isBusClockOn)(void); /* 0xC */
} SceKernelSm1Ops;

types.15_SceSysEventHandler:
typedef struct SceSysEventHandler {
    s32 size;
    const char *name;
    s32 typeMask;
    s32 (*handler)(s32 ev, const char *name, void *param, s32 *result);
    s32 gp;
    s32 busy;
    struct SceSysEventHandler *next;
    s32 reserved[9];
} SceSysEventHandler;

types.30_SceNandInfo:
/* NAND chip geometry (g_nandInfo); filled by sceNandDetectChip */
typedef struct {
    s32 pageSize;      /* 0x0 */
    s32 pagesPerBlock; /* 0x4 */
    s32 totalBlocks;   /* 0x8 */
    u8 makerId;        /* 0xC */
    u8 deviceId;       /* 0xD */
    u8 padE[2];
} SceNandInfo;
/* known chip table entry (D_00002860, 17 entries) */
typedef struct {
    u8 makerId;         /* 0x0 */
    u8 deviceId;        /* 0x1 */
    u16 pageSize;       /* 0x2 */
    u16 pagesPerBlock;  /* 0x4 */
    u16 unk6;
    u32 totalBlocks;    /* 0x8 */
} SceNandChipEntry;
typedef char chk_SceNandChipEntry[(sizeof(SceNandChipEntry) == 0xC) ? 1 : -1];

types.35_SceNandSpare:
/* spare area without the user ECC (sceNandReadPages/WritePages "spare" buffers) */
typedef struct {
    u8 blockFmt;    /* 0x0 */
    u8 blockStat;   /* 0x1: 0xFF = good block */
    u16 lbn;        /* 0x2 */
    u32 id;         /* 0x4 */
    u8 spareEcc[2]; /* 0x8 */
    u8 reserved[2]; /* 0xA */
} SceNandSpareExtra;
/* raw spare area (sceNandReadPagesRawAll) */
typedef struct {
    u8 userEcc[3];  /* 0x0 */
    u8 reserved0;   /* 0x3 */
    SceNandSpareExtra extra; /* 0x4 */
} SceNandSpare;
typedef char chk_SceNandSpare[(sizeof(SceNandSpare) == 0x10) ? 1 : -1];
